import {active} from './workflow.js';
import {STATUS,seedCRM,applyCRM,statusOf,agentNames,projectNames} from './crm.js';
let clock=new Date().toISOString(),store=seedCRM(clock),view='Dashboard',role='Manager',dark=false;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v?new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
const users=()=>agentNames(store),projects=()=>projectNames(store),leads=()=>store.leads.filter(l=>role==='Manager'||l.owner===role);
function notify(m){const t=document.querySelector('#toast');t.textContent=m;t.hidden=false;setTimeout(()=>t.hidden=true,3500)}
function nav(x){return `<button data-view="${x}" class="${view===x?'selected':''}">${x}</button>`}
function title(h,p=''){return `<div class="page-heading"><div><h1>${esc(h)}</h1><p>${esc(p)}</p></div></div>`}
function shell(body){app.innerHTML=`<header><button class="brand" data-view="Dashboard">⌂ Home Locator <small>CRM DEMO</small></button><nav>${nav('Dashboard')}${nav('Leads')}${nav('Process')}${nav('Reports')}${nav('Settings')}</nav><div class="top-actions"><select id="role">${['Manager',...users()].map(x=>`<option ${x===role?'selected':''}>${esc(x)}</option>`).join('')}</select><button data-action="theme">${dark?'☀':'◐'}</button></div></header><main><div class="context-bar"><span>INDEPENDENT DEMO · FICTIONAL DATA</span><span>Demo time: ${fmt(clock)} <button data-action="advance">+1 day</button></span></div>${body}<footer>Session-only demo · Refresh resets changes</footer></main>`;document.documentElement.dataset.theme=dark?'dark':'light'}
function dashboard(){const ls=leads();return `<section>${title('Dashboard','Home Locator CRM workflow demo')}<div class="cards"><div><b>${ls.length}</b><span>Visible Leads</span></div><div><b>${ls.filter(l=>active(l)).length}</b><span>Active</span></div><div><b>${store.tasks.filter(t=>t.status==='Open').length}</b><span>Open Tasks</span></div><div><b>${store.visits.filter(v=>v.status==='Scheduled').length}</b><span>Scheduled Visits</span></div></div><div class="panel"><h2>Quick actions</h2><div class="actions"><button class="primary" data-action="addLead">+ Add Lead</button><button data-view="Leads">View Leads</button><button data-view="Process">Workflow Logic</button></div></div></section>`}
function leadList(){const rows=leads();return `<section>${title('Leads','Manage fictional real-estate enquiries')}<div class="actions"><button class="primary" data-action="addLead">+ Add Lead</button></div><div class="panel"><table><thead><tr><th>Name</th><th>Phone</th><th>Project</th><th>Status</th><th>Owner</th><th>Next task</th></tr></thead><tbody>${rows.map(l=>{const t=store.tasks.find(x=>x.leadId===l.id&&x.status==='Open');return `<tr><td><button class="link" data-action="lead" data-id="${l.id}">${esc(l.name)}</button></td><td>${esc(l.phone)}</td><td>${esc(l.project||'—')}</td><td><span class="badge">${esc(statusOf(l))}</span></td><td>${esc(l.owner)}</td><td>${t?fmt(t.due):'—'}</td></tr>`}).join('')}</tbody></table></div></section>`}
function process(){return `<section>${title('Process','Lead workflow states')}<div class="cards">${STATUS.map(s=>`<div><b>${leads().filter(l=>statusOf(l)===s).length}</b><span>${esc(s)}</span></div>`).join('')}</div></section>`}
function simple(name,desc){return `<section>${title(name,desc)}<div class="panel"><p>This CRM module is included in the prototype. Use Leads for the primary workflow and Settings for session data.</p><div class="actions"><button data-view="Leads">Open Leads</button></div></div></section>`}
function settings(){return `<section>${title('Settings','Session-only demo configuration')}<div class="panel"><h2>Users</h2>${users().map(x=>`<p>${esc(x)}</p>`).join('')}<h2>Projects</h2>${projects().map(x=>`<p>${esc(x)}</p>`).join('')}</div></section>`}
function render(){shell(view==='Dashboard'?dashboard():view==='Leads'?leadList():view==='Process'?process():view==='Settings'?settings():simple(view,'CRM module'))}
function addLead(){modal.innerHTML=`<form><h2>Add Lead</h2><label>Name<input name="name" required></label><label>Phone<input name="phone" required></label><label>Email<input name="email" type="email"></label><label>Project<select name="project">${projects().map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Owner<select name="owner">${users().filter(x=>x!=='Manager').map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><div class="form-footer"><button type="button" data-action="closeModal">Cancel</button><button class="primary" type="submit">Create Lead</button></div></form>`;modal.showModal();modal.querySelector('form').addEventListener('submit',e=>{e.preventDefault();try{const r=applyCRM(store,{type:'createLead',data:Object.fromEntries(new FormData(e.currentTarget))},clock,role);store=r.state;modal.close();render();notify(r.message)}catch(err){notify(err.message)}})}
function leadDetail(id){const l=store.leads.find(x=>x.id===id);if(!l)return;const t=store.tasks.find(x=>x.leadId===id&&x.status==='Open');modal.innerHTML=`<form method="dialog"><h2>${esc(l.name)}</h2><p>${esc(l.phone)} · ${esc(l.email||'')}</p><p>Project: ${esc(l.project||'—')}</p><p>Status: <b>${esc(statusOf(l))}</b></p><p>Owner: ${esc(l.owner)}</p><p>Next follow-up: ${t?fmt(t.due):'—'}</p><div class="form-footer"><button>Close</button></div></form>`;modal.showModal()}
document.addEventListener('click',e=>{const v=e.target.closest('[data-view]');if(v){view=v.dataset.view;render();return}const a=e.target.closest('[data-action]');if(!a)return;switch(a.dataset.action){case'theme':dark=!dark;render();break;case'advance':clock=new Date(Date.parse(clock)+86400000).toISOString();render();break;case'addLead':addLead();break;case'lead':leadDetail(a.dataset.id);break;case'closeModal':modal.close();break}});
document.addEventListener('change',e=>{if(e.target.id==='role'){role=e.target.value;render()}});render();
